INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4984291, 722655, 61961, '<td valign="top">Glad to know you didn''t bend the rules.  I think what confused me about the person on the ground is that she appears out of proportion (too small) compared to the walking man -- which is why I thought she was added to the image digitally.  Plus it''s hard to tell, but it''s almost as if she has a metallic mask covering her face.  Anyway, intriguing image!</td>', 'Glad to know you didn''t bend the rules.  I think what confused me about the person on the ground is that she appears out of proportion (too small) compared to the walking man -- which is why I thought she was added to the image digitally.  Plus it''s hard to tell, but it''s almost as if she has a metallic mask covering her face.  Anyway, intriguing image!', '2008-10-01 10:48:17.000000', NULL, 0),
(4984642, 724458, 50695, '<td valign="top">Fantastic shot! Too bad I didn''t vote this challenge.</td>', 'Fantastic shot! Too bad I didn''t vote this challenge.', '2008-10-01 12:56:38.000000', NULL, 0),
